import math
import fractions

def is_perfect_square(n):
    if n < 0:
        return False
    if n == 0:
        return True
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def is_rational_square(numerator, denominator):
    # Check if numerator and denominator (after simplification) are perfect squares
    common = math.gcd(abs(numerator), abs(denominator))
    num_reduced = numerator // common
    den_reduced = denominator // common

    # Since we are looking for b^2, we expect positive results, so we handle signs implicitly
    if num_reduced < 0 or den_reduced < 0:
        return False # Should not happen for b^2 if a is an integer and a != 2

    return is_perfect_square(num_reduced) and is_perfect_square(den_reduced)

# Test integer values for a in a given range, excluding a=0 and a=2
a_values = list(range(-5, 6))
a_values = [a for a in a_values if a != 0 and a != 2]

results = {}

for a in a_values:
    # Calculate b^2 = (a^3 - 2a^2 - a) / (a - 2)
    numerator = a**3 - 2*a**2 - a
    denominator = a - 2

    # b^2 is guaranteed to be rational since a is an integer

    # Check if numerator/denominator is a rational square
    is_sq = is_rational_square(numerator, denominator)

    if is_sq:
        results[a] = "Solution Found"
    else:
        # Store the value for reference
        b_squared = fractions.Fraction(numerator, denominator)
        results[a] = b_squared

# Print findings clearly
print("--- Search Results for small integers a ---")
print(f"Solutions found for a: {list(results.keys())[list(results.values()).index('Solution Found')] if 'Solution Found' in results.values() else 'None'}")

for a, value in sorted(results.items()):
    if value == "Solution Found":
        print(f"a = {a}: b^2 is a rational square.")
    else:
        print(f"a = {a}: b^2 = {value}")

